begin;
set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table public.dancer_agreement_versions (
  version text primary key,
  is_current boolean not null default false,
  source_sha256 text not null check (source_sha256 ~ '^[a-f0-9]{64}$'),
  content_sha256 text not null check (content_sha256 ~ '^[a-f0-9]{64}$'),
  document_html text not null,
  consent_text text not null,
  created_at timestamptz not null default now()
);
create unique index dancer_agreement_one_current on public.dancer_agreement_versions (is_current) where is_current;

insert into public.dancer_agreement_versions(version, is_current, source_sha256, content_sha256, document_html, consent_text)
values ('2026-09-17-v4', true, '1632164791070c5684c1f577c03194ed7d465f858a18bb6c561ca272d58f6e1e', '41a406a6ae6d96541e0d34a34412e7500af0987eeead420e86ebfb9754394071', $document$<p>MyDancr.com (&quot;Website&quot;) is a social media website and application service that allows Dancers to upload photos and videos to their profile, (&quot;Service&quot;).</p>
<p>These Terms of Service, together with our Privacy Policy (&quot;Terms&quot;), govern your use of MyDancr.com, including any content, functionality, and services offered on or through the Website. By registering with and usingMyDancr.com, you hereby accept and agree to be bound by and abide by these Terms. If you do not want to agree to these Terms, you must not access or use the Website.</p>
<p>This Website is offered and available to users who are 18 years of age or older. By using this Website, you represent and warrant that you are of legal age to form a binding contract with us and meet all of the foregoing eligibility requirements. If you do not meet all of these requirements, you must not access or use the Website.</p>
<p>These Terms are a binding contract between you, an individual user (&quot;Dancer&quot;;) and MyDancr LLC (“MyDancr LLC or MyDancr”), governing your use of the Website and Service. BY ACCESSING THE WEBSITE AND/OR USING THE SERVICE, YOU AGREE THAT YOU HAVE READ, UNDERSTOOD, AND AGREE TO BE BOUND BY THIS DANCER AGREEMENT. IF YOU DO NOT AGREE, YOU MAY NOT ACCESS OR USE THE SERVICE. CONTACT MYDANCR LLC AT <a href="mailto:support@mydancr.com">support@mydancr.com</a> IF YOU WANT MYDANCR LLC TO SEND YOU A COPY OF THIS AGREEMENT AND MYDANCR LLC’S PRIVACY POLICY.</p>
<p>My Dancr LLC is not a talent agent and is not licensed under  any state as a talent agent or as an employment agent or otherwise, or as a theatrical employment agency or other employment agency, and MyDancr LLC has not promised to procure employment or engagements for any of its performers. The Dancer is responsible for the Dancer&#x27;s own relationship with each club, including classification, pay, tips, fees, scheduling, taxes, licensing, work cards, safety, and conduct. MyDancr does not direct the Dancer&#x27;s performance work, set service prices, collect payment for dancer services, or guarantee customers, shifts, income, or admission.</p>
<p>The Dancer acknowledges that MyDancr is not a security service, emergency-response provider, transportation provider, employer, or operator of any club or venue. For any immediate threat or safety emergency, the Dancer must contact 911, law enforcement, appropriate emergency services, and/or club security. MyDancr support is not an emergency service and does not monitor reports in real time.</p>
<p>The Dancer is responsible for making personal safety and transportation decisions while traveling to a club, entering or remaining at a club, working or performing at a club, leaving a club, and traveling home or to any other destination. To the fullest extent permitted by applicable law, the Dancer knowingly assumes the risks associated with those activities and releases and holds harmless MyDancr and its owners, officers, employees, contractors, affiliates, and agents from claims arising from accidents, transportation, assault, harassment, theft, injury, misconduct, unsafe venue conditions, or the actions of clubs, patrons, employees, drivers, or other third parties during those periods.</p>
<h2 id="dancer-agreement-section-1">ELIGIBILITY AND TRUTHFUL IDENTITY.</h2><p>The Dancer represents that the Dancer is at least 18, is the person operating the account, has legal capacity, and may lawfully work and publish the submitted content. The dancer must provide accurate stage identity and city information and must not use another person&#x27;s documents, likeness, stage identity, or account. A stage name may be public; any legal identity collected independently by a club, tax authority, or other provider is governed by that relationship and applicable law.</p>
<p>The Dancer must maintain all local work cards, entertainer licenses, permits, immigration/work authorization, and club requirements. A MyDancr badge or affiliation does not replace government or club verification.</p>
<h2 id="dancer-agreement-section-2">PROFILE APPROVAL AND CLUB AFFILIATIONS.</h2><p>Before the profile becomes public, the Dancer must make the required eligibility and truthful-account representations, complete the required profile fields, obtain approval of required media, and submit the profile. MyDancr alone decides whether the profile is eligible for publication under its account, profile, media, visibility, and safety rules. A club does not approve the Dancer&#x27;s profile or affiliation. A club affiliation is a separate status established by a validated dressing-room NFC tap and is not a general identity, age, employment, licensing, or safety guarantee.</p>
<p>An affiliation is established automatically when MyDancr validates the Dancer&#x27;s intentional tap on the club&#x27;s official dressing-room NFC tag; no club representative approval or confirmation is required. An authorized club user may remove that affiliation through the venue dashboard. The Dancer may post a club-specific shift or use Working Now at a club only while the applicable NFC-established affiliation is active and must promptly correct an inaccurate schedule or notify MyDancr of an inaccurate affiliation.</p>
<h2 id="dancer-agreement-section-3">PUBLIC PROFILE AND SCHEDULE VISIBILITY.</h2><p>When you publish your profile or schedule, you authorize public display of your stage name, city, approved media, public social links, club affiliations, posted shifts, and Working Now status, as applicable. This information can reveal where you work and when you expect to be there. Public information may be copied or indexed by others. Available profile and schedule controls let you change what MyDancr displays, but MyDancr cannot guarantee removal of copies independently retained by third parties.</p>
<h2 id="dancer-agreement-section-4">WORKING NOW AND NFC PRESENCE EVENTS.</h2><p>Working Now requires an intentional dressing-room NFC tap validated by MyDancr. The Dancer authorizes collection of the club, time of the event, browser or device information, IP address, the applicable NFC tag, and information reasonably necessary to validate the event, operate the time window, and prevent fraud. The Dancer may not share or copy a tag, simulate a tap, use automation, or ask another person to check in.</p>
<p>Working Now is time-limited and does not promise that the Dancer remains continuously on premises or is available to any customer. The Dancer should end an inaccurate status through available controls and notify support of a malfunction.</p>
<h2 id="dancer-agreement-section-5">NFC AND TECHNICAL INTEGRITY.</h2><p>The Dancer may not copy, move, alter, obscure, damage, replace, emulate, relay, or misuse an NFC tag; simulate a tap; falsify redemption or verification information; gain unauthorized access; introduce malicious code; scrape or interfere with the Service; or access data outside their authorized permissions.</p>
<h2 id="dancer-agreement-section-6">NFC ASSURANCE.</h2><p>NFC tags are assigned by purpose and club. A validated tap on an official dressing-room tag establishes the Dancer&#x27;s affiliation and can support time-limited Working Now presence; cashier tags support deal verification. MyDancr&#x27;s technical validation of the NFC event is required, but no club representative approval is required. Tags should be installed in controlled areas and replaced if lost, copied, or compromised. MyDancr does not use geofences or continuous or background location tracking for these functions. The applicable intentional NFC tap is the sole in-club verification event.</p>
<p>MATERIAL TERMS: As provided in greater detail in these Terms, you acknowledge the following:</p>
<p>(a) the Service is licensed, not sold to you, and that you may use the Service only as set forth in this Agreement;</p>
<p>(b) the use of the Service may be subject to separate third-party terms of service and fees, including, without limitation, your mobile network operator’s terms of service and fees, including fees charged for data usage and overage, which are your sole responsibility.</p>
<p>The Service presents pictures of semi-nude and audiovisual works depicting semi-nude females. You understand that by using this Service, and by merely accessing this Website, you may be exposed to content that can be considered by some to be offensive, indecent, or objectionable.</p>
<p>You agree not to reproduce, duplicate, copy, sell, distribute, rent, resell or exploit any portion of the Website, Service, use of the Service, or access to the Service; you consent to the collection, use, and disclosure of your personally identifiable information in accordance with MyDancr LLC’s Privacy Policy.</p>
<p>The Website and Service is provided “as is” without warranties of any kind and MyDancr LLC’s liability to you is limited.</p>
<h2 id="dancer-agreement-section-7">SCOPE OF LICENSE.</h2><p>MyDancr provides public promotional profiles, approved photos and videos, MyDancr TV, club affiliations, schedule and Working Now information, and related discovery features. Subject to this Agreement, you may access the Service on compatible devices you own or control and use its authorized features to promote your own lawful professional profile and club appearances. The Service is licensed, not sold, to you for use only under the terms of this agreement, complete and ongoing compliance with the terms of this agreement. MyDancr LLC hereby grants you a personal, limited, revocable, non-transferable license to use the Service on a single compatible device that you own or control, solely for your own private, personal, non-commercial use. You may not make the Service available over a network where it could be used by multiple devices at the same time. You may not rent, lease, lend, redistribute or sublicense the Service. You may not attempt to derive the source code of, modify, or create derivative works of the Service, any updates, or any part thereof (except as and only to the extent any foregoing restriction is prohibited by applicable law). If you breach these license restrictions or the restrictions, or otherwise exceed the scope of the licenses granted herein, then you may be subject to prosecution and damages, as well as liability for infringement of intellectual property rights. The terms of this agreement will govern any updates provided to you by MyDancr LLC that replace and/or supplement the original Terms, unless such upgrade is accompanied by a separate license or revised Terms, in which case the terms of that license or revised Terms will govern.</p>
<p>We reserve the right to make changes to these Terms at any time and at our sole discretion. All changes are effective immediately when we post them and apply to all access to and use of the Website thereafter. By continuing to use MyDancr.com after such notice, you agree to these Terms as modified. You are expected to check this page from time to time so you are aware of any changes, as they are binding on you.</p>
<p>By using MyDancr.com you consent to receiving communications from us electronically, including emails and messages posted to your MyDancr.com account,</p>
<p>You acknowledge and agree that all communications that we provide to you electronically satisfy any legal requirement that such communications be in writing. If you wish to withdraw our consent to receiving communications from us at any time, please email <a href="mailto:support@mydancr.com">support@mydancr.com</a>, notifying us of your withdrawal of consent.</p>
<p>We reserve the right at any time and without notice to:</p>
<p>(a) modify, suspend or terminate the Service or any portion thereof;</p>
<p>(b) restrict, limit, suspend or terminate your access to the Service or any portion thereof;</p>
<p>(c) delete any content you post on MyDancr.com if in our reasonable opinion it does not comply with these Terms and/or applicable law;</p>
<p>(d) monitor your use of the Service (including any content or message you post or broadcast on MyDancr.com) to verify compliance with these Terms and/or any applicable law;</p>
<p>(e) investigate any suspected or alleged misuse or unlawful use of the Service and cooperate with law enforcement in such investigation;</p>
<p>(f) disclose information about your use of the Service in connection with law enforcement investigation of any suspected or alleged illegal activity, or in response to a lawful court order; or</p>
<p>From time to time, we may restrict access to some parts of the Website, or the entire Website, to Dancers.</p>
<h2 id="dancer-agreement-section-8">PRIVACY POLICY.</h2><p>Your use of the Website and Service is subject to the Privacy Policy, which is hereby incorporated by reference into these Terms. By using the Website and/or Service, you agree that you have read, understood, and agree to the data collection, use, and disclosure provisions set forth in the Privacy Policy.</p>
<h2 id="dancer-agreement-section-9">MOBILE SERVICES.</h2><p>The Service includes certain services that are available via a mobile device, including (a) the ability to browse the Service from a mobile device; and (b) the ability to access certain features of the Service through Service Applications downloaded and installed on a mobile device (collectively, the “Mobile Services”). To the extent that you access the Service through a mobile device, your wireless service carrier’s standard charges, data rates and other fees may apply, and you acknowledge that you are solely responsible for all such fees and charges. In addition, your carrier may restrict downloading, installing, or using certain Mobile Services, and not all Mobile Services may work with all carriers or devices.</p>
<h2 id="dancer-agreement-section-10">SERVICE SECURITY.</h2><p>You are prohibited from violating, or attempting to violate, the security of the Service. Any such violations may result in criminal and/or civil penalties against you, as well as the termination of your privilege to use the Service, at MyDancr LLC’s sole discretion. MyDancr LLC reserves the right to investigate any alleged or suspected violations and, if a criminal violation is suspected, refer such suspected violation to the appropriate law enforcement agencies and cooperate fully with such investigations, including, but not limited to, the disclosure of any or all of your activities on or related to the Service. You agree to promptly notify MyDancr LLC if you learn or reasonably suspect that any security breach related to the Service has occurred.</p>
<h2 id="dancer-agreement-section-11">REGISTRATION AND ELIGIBILITY.</h2><p>To access certain additional features and functionality of the Service, you must register an account with MyDancr.com. All information provided to MyDancr LLC during registration will be held and used in accordance with MyDancr.com’s Privacy Policy. You are responsible for maintaining the confidentiality of your log-in credentials in order to use the Service and are fully responsible for all activities that occur through the use of your credentials. You agree to notify MyDancr LLC immediately of any unauthorized use of your log-in credentials or any other breach of security with respect to your account. MyDancr LLC will not be liable for any loss or damage arising from unauthorized use of your credentials prior to you notifying MyDancr LLC of such unauthorized use or loss of your credentials.</p>
<h2 id="dancer-agreement-section-12">ACCURACY OF INFORMATION.</h2><p>You agree to provide true, accurate, current, and complete information about yourself as requested in any registration forms and to update the information about yourself promptly, and as necessary, to keep it current and accurate.</p>
<h2 id="dancer-agreement-section-13">ACCOUNT DEACTIVATION AND DELETION.</h2><p>You may disable or request deletion of your account through Account Settings, or contact <a href="mailto:support@mydancr.com">support@mydancr.com</a> for assistance. Disabling an account and deleting an account have different effects. Account deletion does not necessarily remove records we must retain for the limited purposes described in the Privacy Policy.</p>
<h2 id="dancer-agreement-section-14">ADVERTISEMENTS.</h2>
<p>(a) Third Party Advertisements. MyDancr LLC may display advertisements for the goods and services of third parties or other promotional materials on the Service. Your dealings with, or participation in, promotions of any third-party advertisers on the Service, are solely between you and such third party, and your participation is subject to any terms and conditions associated with that advertisement or promotion. MyDancr LLC does not endorse or represent such third parties, and by using the Service, you agree that MyDancr LLC is not responsible or liable for any loss or damage of any sort incurred as a result of any such dealings or the presence of such third parties on the Service.</p>
<p>(b) Third Party Sites. The Service may also include links to third party websites or third-party services that are not owned or operated by MyDancr LLC (collectively, “Third-Party Sites”). MyDancr LLC does not endorse or represent such third parties andMyDancr LLC is not responsible for the availability of these Third-Party Sites, or any products, services and/or content contained therein. You agree that we are not responsible or liable, directly or indirectly, for any loss or damage of any sort incurred as a result of your use of or reliance on any Third-Party Sites. Certain functionalities of the Service may also require that you agree to additional terms and conditions of Third-Party Sites. You agree that you are solely responsible for your acceptance of and compliance with such terms and conditions whenever you use or access such Third-Party Sites.</p>
<p>(c) Social links and off-platform conduct. Supported social links may be displayed as &quot;Social links&quot; or equivalent neutral wording. The Dancer must control or be authorized to link each account. Links may not be used to evade MyDancr rules, solicit prohibited services, direct minors, mislead customers, or distribute malware. Third-party platform terms apply.</p>
<p>MyDancr does not monitor all off-platform conduct, but conduct connected to the Service may support enforcement when it creates safety, fraud, trafficking, impersonation, or legal risk.</p>
<p>CONTENT YOU SUBMIT; LICENSE GRANTS FROM YOU. A. Dancer Content. This Section governs any material that you post, send or transmit (collectively, “Post”) through the Service, including, by way of example and not limitation, photographs, graphics, images, text, musical works, sound recordings, digital phonorecord deliveries, and any other content, materials or works subject to protection under the laws of the United States or any other jurisdiction, including, but not limited to, patent, trademark, trade secret, and copyright laws (collectively, “Dancer Content”). You are solely responsible for securing the rights to any and all Dancer Content you Post to or through the Service.</p>
